UPDATE truss.key_bucket_guard SET generation = generation WHERE namespace_sha256 = $1::bytea AND key_sha256 = $2::bytea RETURNING generation::text; INSERT INTO truss.key_bucket_guard (namespace_sha256, key_sha256, generation) VALUES ($1::bytea, $2::bytea, 0) RETURNING generation::text; SELECT storage_row_id::text AS storage_row_id, octet_length(namespace_bytes)::text AS namespace_bytes_length, octet_length(key_bytes)::text AS key_bytes_length, octet_length(original_context_bytes)::text AS original_artifact_bytes_length FROM truss.object_key_bucket WHERE namespace_sha256 = $1::bytea AND key_sha256 = $2::bytea ORDER BY storage_row_id LIMIT 10001; SELECT storage_row_id::text AS storage_row_id, octet_length(namespace_bytes)::text AS namespace_bytes_length, octet_length(key_bytes)::text AS key_bytes_length, octet_length(original_reservation_bytes)::text AS original_artifact_bytes_length FROM truss.object_key_reservation_bucket WHERE namespace_sha256 = $1::bytea AND key_sha256 = $2::bytea ORDER BY storage_row_id LIMIT 10001; SELECT storage_row_id::text AS storage_row_id, type_id::text AS type_id, key_num::text AS key_num, object_id::text AS object_id, namespace_bytes, key_bytes, original_context_bytes FROM truss.object_key_bucket WHERE namespace_sha256 = $1::bytea AND key_sha256 = $2::bytea AND storage_row_id = ANY($3::bigint[]) ORDER BY storage_row_id; SELECT storage_row_id::text AS storage_row_id, namespace_bytes, key_bytes, original_reservation_bytes FROM truss.object_key_reservation_bucket WHERE namespace_sha256 = $1::bytea AND key_sha256 = $2::bytea AND storage_row_id = ANY($3::bigint[]) ORDER BY storage_row_id; UPDATE truss.key_bucket_guard SET generation = generation + $3::bigint WHERE namespace_sha256 = $1::bytea AND key_sha256 = $2::bytea AND $3::bigint > 0 AND generation <= (9223372036854775807 - $3::bigint) RETURNING generation::text